def main() -> int:
    if not (os.path.isdir("src/quadcoop") and os.path.isdir("slurm")):
        print("run this from the repo root (the folder with src/quadcoop and slurm)")
        return 1
    bad = 0
    for path, (sha, known, executable, b64) in FILES.items():
        data = base64.b64decode("".join(b64.split()))
        if hashlib.sha256(data).hexdigest() != sha:
            print(f"DAMAGED in this script, skipped: {path}")
            bad += 1
            continue
        if os.path.exists(path):
            old = open(path, "rb").read()
            if old == data:
                print(f"unchanged  {path}")
                continue
            if hashlib.sha256(old).hexdigest() not in known:
                os.replace(path, path + ".orig")
                print(f"(your edited copy kept as {path}.orig)")
            status = "updated"
        else:
            status = "new    "
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        if executable:
            os.chmod(path, 0o755)
        print(f"{status}    {path}")
    if bad:
        print(f"{bad} file(s) damaged: download install_stage2.py again (do not copy-paste it)")
        return 1
    print("done: all files written and verified")
    return 0


if __name__ == "__main__":
    sys.exit(main())